// ===== Generado por calculo/exportar-n8n.js. No editar aquí: editar calculo/ y flujos/n8n/src/ =====
const UMBRALES = { compaRatio: 0.9, mesesSinRevision: 18, evaluacionAlta: 4, mesesManagerReciente: 6, nMinimoEncuesta: 5 };
const ORDEN = { verde: 0, ambar: 1, rojo: 2 };
const PUNTOS_SEMAFORO = { rojo: 3, ambar: 2, verde: 0 };
const PUNTOS_CRITICIDAD = { critica: 3, importante: 2, soporte: 1 };

// ---------- Cálculo ----------
function prioridad(semaforo, criticidad) {
  const p = PUNTOS_SEMAFORO[semaforo] * PUNTOS_CRITICIDAD[criticidad];
  return p >= 9 ? 'P1' : p >= 6 ? 'P2' : p >= 3 ? 'P3' : p >= 2 ? 'P4' : '-';
}

function calcular(datos) {
  const { funciones, empleados, skills, planes, catalogo } = datos;
  const objetivoDefecto = funciones.defaults.cobertura_objetivo;
  const activos = new Map(empleados.filter(e => e.estado === 'activo').map(e => [e.id, e]));
  const nivel = new Map(); // "E007|gestion-claves" -> nivel validado
  for (const s of skills) if (activos.has(s.empleado_id) && s.nivel_validado) nivel.set(`${s.empleado_id}|${s.skill_id}`, +s.nivel_validado);
  const nivelDe = (id, skill) => nivel.get(`${id}|${skill}`) || 0;
  const interes = id => (activos.get(id).skills_interes || '').split(';').filter(Boolean);
  const planesActivos = planes.filter(p => p.estado === 'activo' && activos.has(p.empleado_id));

  // 1. Cobertura y semáforo por skill y por función
  const resultado = funciones.funciones.map(f => {
    const objetivo = f.cobertura_objetivo || objetivoDefecto;
    const skillsF = f.skills_requeridas.map(({ skill, nivel: min }) => {
      const cubren = [...activos.keys()].filter(id => nivelDe(id, skill) >= min);
      const backups = planesActivos
        .filter(p => p.skill_id === skill && nivelDe(p.empleado_id, skill) === min - 1)
        .map(p => p.empleado_id);
      const n = cubren.length;
      const semaforo = n >= objetivo ? 'verde' : n >= 2 ? 'ambar' : n === 1 && backups.length ? 'ambar' : 'rojo';
      return { skill, nivel_minimo: min, cobertura: n, personas: cubren, backups_en_desarrollo: backups, semaforo };
    });
    const peor = skillsF.reduce((a, b) => (ORDEN[b.semaforo] > ORDEN[a.semaforo] || (b.semaforo === a.semaforo && b.cobertura < a.cobertura) ? b : a));
    // Lente AI first (reglas-semaforo.md §7): en rojo con impacto IA alto no se forma un backup del proceso actual
    const respuesta = peor.semaforo === 'rojo' && f.impacto_ia === 'alto' ? 'redisenar' : 'cubrir';
    return {
      id: f.id, nombre: f.nombre, area: f.area, criticidad: f.criticidad, impacto_ia: f.impacto_ia, objetivo,
      cobertura: Math.min(...skillsF.map(s => s.cobertura)),
      semaforo: peor.semaforo, prioridad: prioridad(peor.semaforo, f.criticidad), respuesta, skills: skillsF,
    };
  });

  // 2. Key people: única cobertura de una skill en función crítica o importante
  const keyPeople = new Map();
  for (const f of resultado) {
    if (f.criticidad === 'soporte') continue;
    for (const s of f.skills) if (s.cobertura === 1) {
      const id = s.personas[0];
      if (!keyPeople.has(id)) keyPeople.set(id, []);
      keyPeople.get(id).push({ funcion: f.id, skill: s.skill, semaforo: f.semaforo });
    }
  }

  // 3. Candidatos a backup y formación para skills en rojo/ámbar
  for (const f of resultado) for (const s of f.skills) {
    if (s.semaforo === 'verde') continue;
    s.candidatos = [...activos.keys()]
      .filter(id => nivelDe(id, s.skill) === s.nivel_minimo - 1 && !s.backups_en_desarrollo.includes(id))
      .map(id => ({ id, nombre: activos.get(id).nombre, area: activos.get(id).area, con_interes: interes(id).includes(s.skill), es_key_person: keyPeople.has(id) }))
      .sort((a, b) => b.con_interes - a.con_interes || a.es_key_person - b.es_key_person);
    // Un mentoring interno necesita a alguien que ya cubra la skill: con cobertura 0 no se propone
    s.formacion = catalogo.filter(c => c.skill === s.skill && c.a === s.nivel_minimo && !(c.tipo === 'mentoring-interno' && s.cobertura === 0)).map(c => c.id);
  }

  // 4. Señales de rotación (solo key people y personas que cubren funciones en rojo/ámbar)
  const enRiesgo = new Set(keyPeople.keys());
  for (const f of resultado) if (f.semaforo !== 'verde') for (const s of f.skills) if (s.semaforo !== 'verde') s.personas.forEach(id => enRiesgo.add(id));
  const senales = [...enRiesgo].map(id => ({ id, nombre: activos.get(id).nombre, ...senalesRotacion(activos.get(id), datos) }));

  return {
    funciones: resultado,
    key_people: [...keyPeople].map(([id, funcs]) => {
      const e = activos.get(id);
      const areaDe = fid => resultado.find(f => f.id === fid).area;
      // Oculta: puesto junior/intermedio, o sostiene una función de otra área (reglas-semaforo.md §3)
      const oculta = ['junior', 'intermedio'].includes(e.nivel_puesto) || funcs.some(f => areaDe(f.funcion) !== e.area);
      return { id, nombre: e.nombre, area: e.area, rol: e.rol, nivel_puesto: e.nivel_puesto, oculta, funciones: funcs };
    }),
    senales_rotacion: senales,
    madurez_ia: madurezIa(datos),
  };
}

// Madurez IA por área: nivel medio validado de cada skill de IA (sin la skill = 0).
// Áreas con menos de 5 personas se agrupan en su división, como las encuestas; si aun así no llegan a 5,
// no se publican. Así no se puede deducir el nivel de nadie.
function madurezIa(datos) {
  const skillsIa = datos.taxonomia.skills.filter(s => s.tipo === 'ia').map(s => s.id);
  const activos = datos.empleados.filter(e => e.estado === 'activo');
  const nivel = new Map(datos.skills.filter(s => s.nivel_validado).map(s => [`${s.empleado_id}|${s.skill_id}`, +s.nivel_validado]));
  const grupos = new Map();
  const cuenta = activos.reduce((m, e) => ((m[e.area] = (m[e.area] || 0) + 1), m), {});
  for (const e of activos) {
    const seg = cuenta[e.area] >= UMBRALES.nMinimoEncuesta ? e.area : `${datos.areas[e.area]} (áreas pequeñas)`;
    if (!grupos.has(seg)) grupos.set(seg, []);
    grupos.get(seg).push(e.id);
  }
  const media = ids => Object.fromEntries(skillsIa.map(s => [s, +(ids.reduce((t, id) => t + (nivel.get(`${id}|${s}`) || 0), 0) / ids.length).toFixed(1)]));
  return [...grupos].filter(([, ids]) => ids.length >= UMBRALES.nMinimoEncuesta).map(([segmento, ids]) => {
    const m = media(ids);
    return { segmento, n: ids.length, ...m, indice: +(skillsIa.reduce((t, s) => t + m[s], 0) / skillsIa.length).toFixed(1) };
  }).sort((a, b) => b.indice - a.indice);
}

function climaDe(area, datos) {
  const enc = datos.encuesta;
  const fila = (tipo, seg) => enc.find(r => r.segmento_tipo === tipo && r.segmento === seg && r.publicable === 'si' && +r.n >= UMBRALES.nMinimoEncuesta);
  return fila('area', area) || fila('division', datos.areas[area]) || null;
}

function senalesRotacion(e, datos) {
  const banda = datos.bandas.find(b => b.banda_id === e.banda_id);
  const compa = +(e.salario_ficticio / banda.medio).toFixed(2);
  const media = +datos.encuesta.find(r => r.segmento_tipo === 'compania').engagement;
  const clima = climaDe(e.area, datos);
  const activas = [];
  if (compa < UMBRALES.compaRatio) activas.push(`S1 compa-ratio ${compa}`);
  if (+e.meses_desde_ultima_revision > UMBRALES.mesesSinRevision) activas.push(`S2 ${e.meses_desde_ultima_revision} meses sin revisión`);
  if (clima && +clima.engagement < media) activas.push(`S3 clima ${clima.segmento} ${clima.engagement} < ${media}`);
  if (+e.ultima_evaluacion >= UMBRALES.evaluacionAlta) activas.push(`S4 evaluación ${e.ultima_evaluacion}`);
  if (+e.meses_con_manager_actual <= UMBRALES.mesesManagerReciente) activas.push(`S5 ${e.meses_con_manager_actual} meses con su manager`);
  const probabilidad = activas.length >= 3 ? 'alta' : activas.length === 2 ? 'media' : 'baja';
  return { compa_ratio: compa, senales: activas, probabilidad };
}

// ---------- Escenarios ----------
function simularBaja(datos, id) {
  return { ...datos, empleados: datos.empleados.map(e => (e.id === id ? { ...e, estado: 'baja' } : e)) };
}
function simularBackup(datos, empleado, skill, funcion) {
  const plan = { plan_id: 'SIM', empleado_id: empleado, skill_id: skill, funcion_id: funcion || '', estado: 'activo' };
  return { ...datos, planes: [...datos.planes, plan] };
}

// ---------- Vacante y movilidad interna (reglas-semaforo.md §9) ----------
// Perfil del puesto que deja una persona: las skills que cubría en alguna función, con el nivel mínimo más alto
// que le pedían, y liderazgo si tenía equipo. Candidatos internos: quien cumple al menos la mitad del perfil.
const NIVEL_LIDERAZGO_VACANTE = 2;
function vacante(datos, id, despues = calcular(simularBaja(datos, id))) {
  const sale = datos.empleados.find(e => e.id === id);
  const nivel = new Map(datos.skills.filter(s => s.nivel_validado).map(s => [`${s.empleado_id}|${s.skill_id}`, +s.nivel_validado]));
  const niv = (e, skill) => nivel.get(`${e}|${skill}`) || 0;
  const req = new Map();
  for (const f of datos.funciones.funciones) for (const s of f.skills_requeridas)
    if (niv(id, s.skill) >= s.nivel && (!req.has(s.skill) || s.nivel > req.get(s.skill).nivel)) req.set(s.skill, { skill: s.skill, nivel: s.nivel, funcion: f.id });
  const equipo = datos.empleados.filter(e => e.manager_id === id && e.estado === 'activo').map(e => e.id);
  if (equipo.length) req.set('liderazgo', { skill: 'liderazgo', nivel: NIVEL_LIDERAZGO_VACANTE, funcion: '' });
  const perfil = [...req.values()];

  const cobertura = skill => datos.empleados.filter(e => e.estado === 'activo' && e.id !== id && niv(e.id, skill) >= (req.get(skill)?.nivel || 1)).length;
  const keyPeople = new Map(despues.key_people.map(k => [k.id, k.funciones.map(f => f.funcion)]));
  const candidatos = datos.empleados.filter(e => e.estado === 'activo' && e.id !== id).map(e => {
    const brechas = perfil.filter(p => niv(e.id, p.skill) < p.nivel).map(p => ({
      skill: p.skill, tiene: niv(e.id, p.skill), necesita: p.nivel, funcion: p.funcion,
      formacion: datos.catalogo.filter(c => c.skill === p.skill && c.de === niv(e.id, p.skill) && c.a === p.nivel
        && !(c.tipo === 'mentoring-interno' && cobertura(p.skill) === 0)).map(c => c.id),
    }));
    return { id: e.id, nombre: e.nombre, rol: e.rol, area: e.area, cumple: perfil.length - brechas.length, de: perfil.length, brechas, key_person_en: keyPeople.get(e.id) || [] };
  }).filter(c => c.cumple >= Math.ceil(c.de / 2))
    .sort((a, b) => b.cumple - a.cumple || a.brechas.reduce((t, x) => t + x.necesita - x.tiene, 0) - b.brechas.reduce((t, x) => t + x.necesita - x.tiene, 0))
    .slice(0, 3);
  return { id, nombre: sale.nombre, rol: sale.rol, area: sale.area, equipo: equipo.length, perfil, candidatos };
}

// Aprobar la opción interna: el candidato asume el puesto (rol, nivel, manager), el equipo pasa a depender de él
// y se abre un plan por cada brecha de un nivel que tenga formación en el catálogo. Devuelve filas nuevas, no escribe nada.
function aplicarMovilidad(empleados, vac, candidatoId, fecha, origen) {
  const sale = empleados.find(e => e.id === vac.id);
  const nuevos = empleados.map(e =>
    e.id === candidatoId ? { ...e, rol: sale.rol, nivel_puesto: sale.nivel_puesto, manager_id: sale.manager_id, meses_con_manager_actual: '0' }
      : e.manager_id === vac.id && e.estado === 'activo' ? { ...e, manager_id: candidatoId, meses_con_manager_actual: '0' } : e);
  const c = vac.candidatos.find(x => x.id === candidatoId);
  const planes = c.brechas.filter(b => b.necesita - b.tiene === 1 && b.formacion.length).map(b => ({
    empleado_id: candidatoId, skill_id: b.skill, nivel_objetivo: b.necesita, funcion_id: b.funcion, formacion_id: b.formacion[0],
    fecha_inicio: fecha, fecha_objetivo: '', estado: 'activo', origen,
  }));
  return { empleados: nuevos, planes };
}

// Compara con una foto anterior: funciones que empeoran o mejoran
function comparar(antes, despues) {
  const previo = new Map(antes.funciones.map(f => [f.id, f]));
  return despues.funciones.flatMap(f => {
    const a = previo.get(f.id);
    if (!a) return [];
    // Cambio de color, o cambio de cobertura sin cambiar de color fuera del verde
    const d = ORDEN[f.semaforo] - ORDEN[a.semaforo] || (f.semaforo !== 'verde' ? a.cobertura - f.cobertura : 0);
    if (!d) return [];
    return [{ id: f.id, nombre: f.nombre, cambio: d > 0 ? 'empeora' : 'mejora', de: a.semaforo, a: f.semaforo, cobertura_antes: a.cobertura, cobertura_despues: f.cobertura }];
  });
}


// Propuesta de acciones (pasos 4-5): contexto para Claude y propuesta por reglas si no hay IA.
// Sin dependencias: lo usan la demo local (demo.js) y el nodo de código de n8n (exportar-n8n.js).

function contexto(r, cambios, evento, vac, datos) {
  const ids = cambios.filter(c => c.cambio === 'empeora').map(c => c.id);
  const afectadas = r.funciones.filter(x => ids.includes(x.id));
  const implicadas = new Set(afectadas.flatMap(x => x.skills.filter(s => s.semaforo !== 'verde').flatMap(s => s.personas)));
  const formaciones = new Set(afectadas.flatMap(x => x.skills.flatMap(s => s.formacion || [])));
  // Si alguna función se rediseña con IA, la recualificación sale de las formaciones de IA del catálogo
  if (afectadas.some(x => x.respuesta === 'redisenar')) datos.catalogo.filter(c => c.skill.startsWith('ia-')).forEach(c => formaciones.add(c.id));
  if (vac) {
    // Lente AI first: una skill del puesto que solo sostiene funciones a rediseñar no se cubre tal cual (ni dentro ni fuera)
    vac.perfil.forEach(p => { p.redisenar = !!p.funcion && r.funciones.find(f => f.id === p.funcion)?.respuesta === 'redisenar'; });
    vac.candidatos.forEach(c => { implicadas.add(c.id); c.brechas.forEach(b => b.formacion.forEach(x => formaciones.add(x))); });
    // Solo People: compa-ratio del candidato frente a la banda del puesto que asumiría
    const banda = datos.bandas.find(b => b.banda_id === datos.empleados.find(e => e.id === vac.id).banda_id);
    vac.candidatos.forEach(c => { c.compa_en_puesto = +(datos.empleados.find(e => e.id === c.id).salario_ficticio / banda.medio).toFixed(2); c.banda_puesto = banda.banda_id; });
  }
  return {
    evento, cambios, funciones_afectadas: afectadas, key_people: r.key_people, vacante: vac,
    senales: r.senales_rotacion.filter(s => implicadas.has(s.id)),
    catalogo: datos.catalogo.filter(c => formaciones.has(c.id)),
  };
}

// Decisión de cubrir el puesto: dos opciones excluyentes con el mismo grupo (A fuera, B el mejor candidato interno)
function opcionesVacante(ctx) {
  const v = ctx.vacante;
  if (!v || !v.perfil.some(p => p.skill !== 'liderazgo' && !p.redisenar)) return [];
  const grupo = `VAC-${v.id}`;
  const prioridad = ctx.funciones_afectadas.map(x => x.prioridad).sort()[0] || 'P1';
  const ops = [{ prioridad, funcion_id: '', tipo: 'contratar', grupo, accion: `Opción A · Buscar fuera: ${v.rol} (${v.perfil.filter(p => !p.redisenar).map(p => `${p.skill} ${p.nivel}`).join(', ')})`, empleado_id: '', skill_id: '', formacion_id: '',
    por_que: v.candidatos.length ? 'Nadie dentro cumple el perfil completo.' : 'Ningún candidato interno cumple la mitad del perfil.',
    riesgo_si_no: `Proceso de 2-3 meses; mientras tanto, ${v.equipo ? `${v.equipo} personas sin responsable` : 'sus funciones dependen de quien quede'}.` }];
  const c = v.candidatos[0];
  if (c) {
    const conForm = c.brechas.find(b => b.formacion.length);
    ops.push({ prioridad, funcion_id: c.brechas.find(b => b.funcion)?.funcion || '', tipo: 'movilidad', grupo, accion: `Opción B · Mover a ${c.nombre} (${c.rol}) a ${v.rol}`, empleado_id: c.id, skill_id: conForm?.skill || '', formacion_id: conForm?.formacion[0] || '',
      por_que: `Cumple ${c.cumple} de ${c.de} skills del puesto. Le falta: ${c.brechas.map(b => `${b.skill} ${b.tiene} → ${b.necesita}${b.formacion.length ? ` (${b.formacion[0]})` : ' (sin formación en el catálogo)'}`).join('; ')}.`,
      riesgo_si_no: c.key_person_en.length ? `Coste organizativo: ya es la única cobertura de ${c.key_person_en.join(', ')}; asumir el puesto concentra el riesgo en una persona.` : 'Coste organizativo: su puesto actual queda por cubrir.' });
  }
  return ops;
}

function propuestaPorReglas(ctx) {
  const acciones = opcionesVacante(ctx);
  const enVacante = skill => ctx.vacante?.perfil.some(p => p.skill === skill);
  for (const fn of ctx.funciones_afectadas) for (const s of fn.skills.filter(x => x.semaforo !== 'verde')) {
    const cand = (s.candidatos || []).find(c => !c.es_key_person);
    const form = ctx.catalogo.find(c => c.skill === s.skill);
    if (fn.respuesta === 'redisenar') {
      // Lente AI first: no se forma a nadie en el proceso actual; se rediseña y se recualifica
      const formIa = ctx.catalogo.find(c => c.skill === 'ia-automatizacion' && c.de === 1);
      acciones.push({ prioridad: fn.prioridad, funcion_id: fn.id, tipo: 'rediseno', accion: `Rediseñar ${fn.nombre} con IA y automatización${cand ? ` y recualificar a ${cand.nombre}` : ''}`, empleado_id: cand?.id || '', skill_id: 'ia-automatizacion', formacion_id: formIa?.id || '', por_que: `Cobertura ${s.cobertura} en ${s.skill} e impacto IA alto: formar un backup en el proceso actual es invertir en un proceso que va a cambiar.${cand?.con_interes ? ` ${cand.nombre} tiene interés declarado.` : ''}`, riesgo_si_no: `${fn.nombre} sigue dependiendo de ${s.cobertura} persona(s) y de un proceso manual.` });
      if (s.cobertura === 0) acciones.push({ prioridad: fn.prioridad, funcion_id: fn.id, tipo: 'redistribuir', accion: `Cubrir ${fn.nombre} con apoyo temporal mientras dura el rediseño`, empleado_id: '', skill_id: s.skill, formacion_id: '', por_que: 'Nadie cubre la skill hoy.', riesgo_si_no: 'La próxima entrega queda sin responsable.' });
    }
    else if (cand && s.cobertura > 0) acciones.push({ prioridad: fn.prioridad, funcion_id: fn.id, tipo: 'backup', accion: `Plan de backup: ${cand.nombre} en ${s.skill} (${s.nivel_minimo - 1} → ${s.nivel_minimo})`, empleado_id: cand.id, skill_id: s.skill, formacion_id: form?.id || '', por_que: `Cobertura ${s.cobertura}. ${cand.nombre} está a un nivel${cand.con_interes ? ' y tiene interés declarado' : ''}.`, riesgo_si_no: `La función ${fn.nombre} depende de ${s.cobertura} persona.` });
    else if (enVacante(s.skill)) { /* la cubre la decisión de la vacante (opciones A/B) */ }
    else acciones.push({ prioridad: fn.prioridad, funcion_id: fn.id, tipo: 'contratar', accion: `Abrir vacante con ${s.skill} nivel ${s.nivel_minimo}`, empleado_id: '', skill_id: s.skill, formacion_id: '', por_que: `Cobertura ${s.cobertura} y ningún candidato interno llega a tiempo.`, riesgo_si_no: `${fn.nombre} queda sin nadie que pueda sostenerla.` });
    if (s.cobertura === 1) {
      const kp = s.personas[0];
      acciones.push({ prioridad: fn.prioridad, funcion_id: fn.id, tipo: 'retencion', accion: `Conversación de permanencia con ${ctx.key_people.find(k => k.id === kp)?.nombre || kp}`, empleado_id: kp, skill_id: s.skill, formacion_id: '', por_que: 'Es la única cobertura de la skill.', riesgo_si_no: 'Una segunda salida deja la función sin cobertura.' });
    }
  }
  const n = ctx.cambios.filter(c => c.cambio === 'empeora').length;
  const nOpciones = acciones.filter(a => a.grupo).length;
  const v = nOpciones ? ctx.vacante : null, c = nOpciones > 1 ? v.candidatos[0] : null;
  const resumen = v
    ? `${ctx.evento}: ${n} función(es) empeoran. Primera decisión: cómo cubrir el puesto de ${v.rol}, buscando fuera (A)${c ? ` o moviendo a ${c.nombre} (B)` : ''}. Además se proponen ${acciones.length - nOpciones} acción(es) para reducir el riesgo mientras tanto. Todo queda pendiente de aprobación por People.`
    : `${ctx.evento}: ${n} función(es) empeoran. Se proponen ${acciones.length} acciones para su aprobación por People.`;
  const sen = c && ctx.senales.find(s => s.id === c.id);
  const detalle = c ? `${c.nombre}: probabilidad ${sen?.probabilidad || 'baja'} (${sen?.senales.join('; ') || 'sin señales'}). Si asume el puesto con su salario actual, su compa-ratio en la banda ${c.banda_puesto} sería ${c.compa_en_puesto}: la opción B exige revisar condiciones.` : '';
  return { acciones, resumen_direccion: resumen, detalle_people: detalle, observaciones: 'Propuesta generada por reglas (sin IA).' };
}

// Mensaje de usuario para prompts/proponer-acciones.md (mismo orden que la sección ## User del prompt)
function mensajeClaude(ctx) {
  const j = v => JSON.stringify(v, null, 1);
  return `Evento: ${ctx.evento}

Cambios en el mapa:
${j(ctx.cambios)}

Funciones afectadas (detalle del cálculo):
${j(ctx.funciones_afectadas)}

Key people tras el cambio:
${j(ctx.key_people)}

Señales de rotación (solo personas implicadas, confidencial People):
${j(ctx.senales)}

Vacante (puesto que deja la persona, si aplica):
${j(ctx.vacante)}

Formaciones disponibles:
${j(ctx.catalogo)}`;
}


// Filas de las hojas calculadas del Sheet (cobertura, key-people, histórico, alertas).
// Sin dependencias: lo usan exportar-sheets.js y los nodos de código de n8n (exportar-n8n.js).

const COLS = {
  cobertura: ['funcion_id', 'area', 'nombre', 'criticidad', 'semaforo', 'icono', 'prioridad', 'cobertura', 'objetivo', 'skill_mas_debil', 'cubren', 'backup_en_desarrollo', 'candidatos_con_interes', 'impacto_ia', 'respuesta'],
  keyPeople: ['empleado_id', 'nombre', 'area', 'rol', 'oculta', 'funciones', 'skills'],
  historico: ['fecha', 'funcion_id', 'semaforo', 'cobertura', 'prioridad', 'evento'],
  alertas: ['alerta_id', 'fecha', 'evento', 'funcion_id', 'prioridad', 'cambio', 'tipo_accion', 'accion', 'empleado_id', 'skill_id', 'formacion_id', 'por_que', 'riesgo_si_no', 'decision', 'decidido_por', 'fecha_decision', 'grupo'],
};
const ICONO = { verde: '🟢', ambar: '🟡', rojo: '🔴' };

function filasCobertura(r, nombre) {
  return r.funciones.map(f => {
    const s = f.skills.reduce((a, b) => (b.cobertura < a.cobertura ? b : a));
    const debiles = f.skills.filter(x => x.semaforo !== 'verde');
    return [f.id, f.area, f.nombre, f.criticidad, f.semaforo, ICONO[f.semaforo], f.prioridad, f.cobertura, f.objetivo, s.skill,
      s.personas.map(nombre).join('; '),
      debiles.flatMap(x => x.backups_en_desarrollo).map(nombre).join('; '),
      debiles.flatMap(x => (x.candidatos || []).filter(c => c.con_interes).map(c => c.nombre)).join('; '),
      f.impacto_ia, f.respuesta === 'redisenar' ? 'rediseñar con IA' : 'cubrir'];
  });
}

function filasKeyPeople(r) {
  return r.key_people.map(k => [k.id, k.nombre, k.area, k.rol, k.oculta ? 'si' : 'no',
    k.funciones.map(f => f.funcion).join('; '), k.funciones.map(f => f.skill).join('; ')]);
}

function filasHistorico(r, fecha, evento) {
  return r.funciones.map(f => [fecha, f.id, f.semaforo, f.cobertura, f.prioridad, evento]);
}


// Utilidades de los nodos de código de n8n: leer las hojas (nodos nativos de Google Sheets) y preparar las filas a escribir.
// exportar-n8n.js las concatena con el motor (cobertura.js), la propuesta (propuesta.js) y las filas (hojas.js).

// Nodo de lectura de cada hoja. bandas y encuesta no cambian en la demo: vienen de definiciones.json (repo).
const LECTURAS = { empleados: 'Leer empleados', 'skills-empleados': 'Leer skills', 'planes-backup': 'Leer planes', alertas: 'Leer alertas', cobertura: 'Leer cobertura' };
// Cómo se escribe cada hoja con el nodo nativo: actualizar por clave, añadir o actualizar por clave, añadir, o vaciar y volver a escribir
const ESCRITURAS = {
  empleados: { op: 'update', clave: 'id' },
  'skills-empleados': { op: 'update', clave: 'row_number' },
  'skills-empleados (nueva)': { op: 'append', hoja: 'skills-empleados' }, // una skill que la persona no tenía
  'planes-backup': { op: 'appendOrUpdate', clave: 'plan_id' },
  alertas: { op: 'appendOrUpdate', clave: 'alerta_id' },
  cobertura: { op: 'appendOrUpdate', clave: 'funcion_id' },
  'historico-semaforo': { op: 'append' },
  'key-people': { op: 'reemplazar' },
};
const hoyISO = () => new Date().toISOString().slice(0, 10);

// Salida de los nodos de lectura → { hoja: { filas: [{ ...columnas, _fila }] } }. _fila es la fila real (row_number).
function tablas() {
  const t = {};
  for (const [hoja, nodo] of Object.entries(LECTURAS)) {
    let items = [];
    try { items = $(nodo).all().map(i => i.json); } catch (err) { /* este workflow no lee esa hoja */ }
    t[hoja] = { filas: items.filter(o => Object.keys(o).some(k => k !== 'row_number' && o[k] !== '' && o[k] != null)).map(o => {
      const f = { _fila: o.row_number };
      for (const [k, v] of Object.entries(o)) if (k !== 'row_number') f[k] = v == null ? '' : String(v);
      return f;
    }) };
  }
  return t;
}

function datosDesde(T, defs) {
  return {
    funciones: defs.funciones, taxonomia: defs.taxonomia, areas: defs.areas, catalogo: defs.catalogo,
    bandas: defs.bandas, encuesta: defs.encuesta,
    empleados: T['empleados'].filas, skills: T['skills-empleados'].filas, planes: T['planes-backup'].filas,
  };
}

// Foto anterior = lo que muestra ahora la hoja cobertura (siempre refleja el último recálculo)
function fotoActual(T) {
  return { funciones: T['cobertura'].filas.map(x => ({ id: x.funcion_id, semaforo: x.semaforo, cobertura: +x.cobertura, nombre: x.nombre })) };
}

// ---------- Filas a escribir: cada una lleva _hoja para que el desvío la mande a su nodo ----------
const valor = v => (v == null ? '' : typeof v === 'string' && /^-?\d+(\.\d+)?$/.test(v) && !/^0\d/.test(v) ? +v : v);
const fila = (hoja, obj, columnas = Object.keys(obj).filter(k => !k.startsWith('_'))) =>
  ({ _hoja: hoja, ...Object.fromEntries(columnas.map(c => [c, valor(obj[c])])) });
const filasDe = (hoja, cols, arrays) => arrays.map(a => fila(hoja, Object.fromEntries(cols.map((c, i) => [c, a[i]]))));

// Mapa tras un recálculo: cobertura (por funcion_id), key-people (se vacía y se reescribe) y foto en el histórico
function filasMapa(r, datos, evento) {
  const nombre = id => datos.empleados.find(e => e.id === id)?.nombre || id;
  return [
    ...filasDe('cobertura', COLS.cobertura, filasCobertura(r, nombre)),
    ...filasDe('key-people', COLS.keyPeople, filasKeyPeople(r)),
    ...filasDe('historico-semaforo', COLS.historico, filasHistorico(r, hoyISO(), evento)),
  ];
}

// ---------- Email (HTML sencillo, se ve bien en Gmail) ----------
const esc = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const html = cuerpo => `<div style="font-family:Arial,sans-serif;font-size:14px;color:#222;max-width:680px">${cuerpo}<p style="color:#888;font-size:12px;margin-top:24px">Acme People OS · datos ficticios · generado automáticamente</p></div>`;
function listaCambios(cambios) {
  return `<ul>${cambios.map(c => `<li><b>${esc(c.id)}</b> ${esc(c.nombre)}: ${ICONO[c.de]} → ${ICONO[c.a]} (cobertura ${c.cobertura_antes} → ${c.cobertura_despues})</li>`).join('')}</ul>`;
}


// ===== Nodo =====
// Escenario 1 (baja) · nodo "Motor": pasos 1-4. Aplica la baja en memoria, recalcula, compara con el mapa actual
// (hoja cobertura) y prepara la petición a Claude.
const cfg = $('Configuración').first().json;
const T = tablas();
const defs = JSON.parse($('Leer definiciones').first().json.definiciones);
const base = datosDesde(T, defs);

const id = String(cfg.empleado_id || '').trim().toUpperCase();
const e = base.empleados.find(x => x.id === id);
if (!e) throw new Error(`No existe ${id} en la hoja empleados`);
if (e.estado !== 'activo') throw new Error(`${e.nombre} ya figura como ${e.estado}. Para repetir la demo, pide a Claude Code "reinicia la demo".`);
const evento = `Baja de ${e.nombre} (${e.rol})`;

const vac = vacante(base, id); // el perfil del puesto se calcula con la persona aún dentro
const datos = simularBaja(base, id);
const r = calcular(datos);
const nombres = new Map(r.funciones.map(f => [f.id, f.nombre]));
const cambios = comparar(fotoActual(T), r).map(c => ({ ...c, nombre: nombres.get(c.id) }));
const ctx = contexto(r, cambios, evento, vac, datos);

const md = defs.prompt_propuesta;
const system = md.split('## System')[1].split('## User')[0].trim();
const conteo = r.funciones.reduce((m, f) => ((m[f.semaforo] = (m[f.semaforo] || 0) + 1), m), {});

return [{ json: {
  id, evento, hay_alerta: cambios.some(c => c.cambio === 'empeora'), cambios, conteo,
  reglas: propuestaPorReglas(ctx), n_alertas: T['alertas'].filas.length,
  filas: [fila('empleados', { id, estado: 'baja' }), ...filasMapa(r, datos, evento)],
  body: { model: cfg.modelo, max_tokens: 4000, system, messages: [{ role: 'user', content: mensajeClaude(ctx) }] },
} }];

// ===== Generado por calculo/exportar-n8n.js. No editar aquí: editar calculo/ y flujos/n8n/src/ =====
const UMBRALES = { compaRatio: 0.9, mesesSinRevision: 18, evaluacionAlta: 4, mesesManagerReciente: 6, nMinimoEncuesta: 5 };
const ORDEN = { verde: 0, ambar: 1, rojo: 2 };
const PUNTOS_SEMAFORO = { rojo: 3, ambar: 2, verde: 0 };
const PUNTOS_CRITICIDAD = { critica: 3, importante: 2, soporte: 1 };

// ---------- Cálculo ----------
function prioridad(semaforo, criticidad) {
  const p = PUNTOS_SEMAFORO[semaforo] * PUNTOS_CRITICIDAD[criticidad];
  return p >= 9 ? 'P1' : p >= 6 ? 'P2' : p >= 3 ? 'P3' : p >= 2 ? 'P4' : '-';
}

function calcular(datos) {
  const { funciones, empleados, skills, planes, catalogo } = datos;
  const objetivoDefecto = funciones.defaults.cobertura_objetivo;
  const activos = new Map(empleados.filter(e => e.estado === 'activo').map(e => [e.id, e]));
  const nivel = new Map(); // "E007|gestion-claves" -> nivel validado
  for (const s of skills) if (activos.has(s.empleado_id) && s.nivel_validado) nivel.set(`${s.empleado_id}|${s.skill_id}`, +s.nivel_validado);
  const nivelDe = (id, skill) => nivel.get(`${id}|${skill}`) || 0;
  const interes = id => (activos.get(id).skills_interes || '').split(';').filter(Boolean);
  const planesActivos = planes.filter(p => p.estado === 'activo' && activos.has(p.empleado_id));

  // 1. Cobertura y semáforo por skill y por función
  const resultado = funciones.funciones.map(f => {
    const objetivo = f.cobertura_objetivo || objetivoDefecto;
    const skillsF = f.skills_requeridas.map(({ skill, nivel: min }) => {
      const cubren = [...activos.keys()].filter(id => nivelDe(id, skill) >= min);
      const backups = planesActivos
        .filter(p => p.skill_id === skill && nivelDe(p.empleado_id, skill) === min - 1)
        .map(p => p.empleado_id);
      const n = cubren.length;
      const semaforo = n >= objetivo ? 'verde' : n >= 2 ? 'ambar' : n === 1 && backups.length ? 'ambar' : 'rojo';
      return { skill, nivel_minimo: min, cobertura: n, personas: cubren, backups_en_desarrollo: backups, semaforo };
    });
    const peor = skillsF.reduce((a, b) => (ORDEN[b.semaforo] > ORDEN[a.semaforo] || (b.semaforo === a.semaforo && b.cobertura < a.cobertura) ? b : a));
    // Lente AI first (reglas-semaforo.md §7): en rojo con impacto IA alto no se forma un backup del proceso actual
    const respuesta = peor.semaforo === 'rojo' && f.impacto_ia === 'alto' ? 'redisenar' : 'cubrir';
    return {
      id: f.id, nombre: f.nombre, area: f.area, criticidad: f.criticidad, impacto_ia: f.impacto_ia, objetivo,
      cobertura: Math.min(...skillsF.map(s => s.cobertura)),
      semaforo: peor.semaforo, prioridad: prioridad(peor.semaforo, f.criticidad), respuesta, skills: skillsF,
    };
  });

  // 2. Key people: única cobertura de una skill en función crítica o importante
  const keyPeople = new Map();
  for (const f of resultado) {
    if (f.criticidad === 'soporte') continue;
    for (const s of f.skills) if (s.cobertura === 1) {
      const id = s.personas[0];
      if (!keyPeople.has(id)) keyPeople.set(id, []);
      keyPeople.get(id).push({ funcion: f.id, skill: s.skill, semaforo: f.semaforo });
    }
  }

  // 3. Candidatos a backup y formación para skills en rojo/ámbar
  for (const f of resultado) for (const s of f.skills) {
    if (s.semaforo === 'verde') continue;
    s.candidatos = [...activos.keys()]
      .filter(id => nivelDe(id, s.skill) === s.nivel_minimo - 1 && !s.backups_en_desarrollo.includes(id))
      .map(id => ({ id, nombre: activos.get(id).nombre, area: activos.get(id).area, con_interes: interes(id).includes(s.skill), es_key_person: keyPeople.has(id) }))
      .sort((a, b) => b.con_interes - a.con_interes || a.es_key_person - b.es_key_person);
    // Un mentoring interno necesita a alguien que ya cubra la skill: con cobertura 0 no se propone
    s.formacion = catalogo.filter(c => c.skill === s.skill && c.a === s.nivel_minimo && !(c.tipo === 'mentoring-interno' && s.cobertura === 0)).map(c => c.id);
  }

  // 4. Señales de rotación (solo key people y personas que cubren funciones en rojo/ámbar)
  const enRiesgo = new Set(keyPeople.keys());
  for (const f of resultado) if (f.semaforo !== 'verde') for (const s of f.skills) if (s.semaforo !== 'verde') s.personas.forEach(id => enRiesgo.add(id));
  const senales = [...enRiesgo].map(id => ({ id, nombre: activos.get(id).nombre, ...senalesRotacion(activos.get(id), datos) }));

  return {
    funciones: resultado,
    key_people: [...keyPeople].map(([id, funcs]) => {
      const e = activos.get(id);
      const areaDe = fid => resultado.find(f => f.id === fid).area;
      // Oculta: puesto junior/intermedio, o sostiene una función de otra área (reglas-semaforo.md §3)
      const oculta = ['junior', 'intermedio'].includes(e.nivel_puesto) || funcs.some(f => areaDe(f.funcion) !== e.area);
      return { id, nombre: e.nombre, area: e.area, rol: e.rol, nivel_puesto: e.nivel_puesto, oculta, funciones: funcs };
    }),
    senales_rotacion: senales,
    madurez_ia: madurezIa(datos),
  };
}

// Madurez IA por área: nivel medio validado de cada skill de IA (sin la skill = 0).
// Áreas con menos de 5 personas se agrupan en su división, como las encuestas; si aun así no llegan a 5,
// no se publican. Así no se puede deducir el nivel de nadie.
function madurezIa(datos) {
  const skillsIa = datos.taxonomia.skills.filter(s => s.tipo === 'ia').map(s => s.id);
  const activos = datos.empleados.filter(e => e.estado === 'activo');
  const nivel = new Map(datos.skills.filter(s => s.nivel_validado).map(s => [`${s.empleado_id}|${s.skill_id}`, +s.nivel_validado]));
  const grupos = new Map();
  const cuenta = activos.reduce((m, e) => ((m[e.area] = (m[e.area] || 0) + 1), m), {});
  for (const e of activos) {
    const seg = cuenta[e.area] >= UMBRALES.nMinimoEncuesta ? e.area : `${datos.areas[e.area]} (áreas pequeñas)`;
    if (!grupos.has(seg)) grupos.set(seg, []);
    grupos.get(seg).push(e.id);
  }
  const media = ids => Object.fromEntries(skillsIa.map(s => [s, +(ids.reduce((t, id) => t + (nivel.get(`${id}|${s}`) || 0), 0) / ids.length).toFixed(1)]));
  return [...grupos].filter(([, ids]) => ids.length >= UMBRALES.nMinimoEncuesta).map(([segmento, ids]) => {
    const m = media(ids);
    return { segmento, n: ids.length, ...m, indice: +(skillsIa.reduce((t, s) => t + m[s], 0) / skillsIa.length).toFixed(1) };
  }).sort((a, b) => b.indice - a.indice);
}

function climaDe(area, datos) {
  const enc = datos.encuesta;
  const fila = (tipo, seg) => enc.find(r => r.segmento_tipo === tipo && r.segmento === seg && r.publicable === 'si' && +r.n >= UMBRALES.nMinimoEncuesta);
  return fila('area', area) || fila('division', datos.areas[area]) || null;
}

function senalesRotacion(e, datos) {
  const banda = datos.bandas.find(b => b.banda_id === e.banda_id);
  const compa = +(e.salario_ficticio / banda.medio).toFixed(2);
  const media = +datos.encuesta.find(r => r.segmento_tipo === 'compania').engagement;
  const clima = climaDe(e.area, datos);
  const activas = [];
  if (compa < UMBRALES.compaRatio) activas.push(`S1 compa-ratio ${compa}`);
  if (+e.meses_desde_ultima_revision > UMBRALES.mesesSinRevision) activas.push(`S2 ${e.meses_desde_ultima_revision} meses sin revisión`);
  if (clima && +clima.engagement < media) activas.push(`S3 clima ${clima.segmento} ${clima.engagement} < ${media}`);
  if (+e.ultima_evaluacion >= UMBRALES.evaluacionAlta) activas.push(`S4 evaluación ${e.ultima_evaluacion}`);
  if (+e.meses_con_manager_actual <= UMBRALES.mesesManagerReciente) activas.push(`S5 ${e.meses_con_manager_actual} meses con su manager`);
  const probabilidad = activas.length >= 3 ? 'alta' : activas.length === 2 ? 'media' : 'baja';
  return { compa_ratio: compa, senales: activas, probabilidad };
}

// ---------- Escenarios ----------
function simularBaja(datos, id) {
  return { ...datos, empleados: datos.empleados.map(e => (e.id === id ? { ...e, estado: 'baja' } : e)) };
}
function simularBackup(datos, empleado, skill, funcion) {
  const plan = { plan_id: 'SIM', empleado_id: empleado, skill_id: skill, funcion_id: funcion || '', estado: 'activo' };
  return { ...datos, planes: [...datos.planes, plan] };
}

// ---------- Vacante y movilidad interna (reglas-semaforo.md §9) ----------
// Perfil del puesto que deja una persona: las skills que cubría en alguna función, con el nivel mínimo más alto
// que le pedían, y liderazgo si tenía equipo. Candidatos internos: quien cumple al menos la mitad del perfil.
const NIVEL_LIDERAZGO_VACANTE = 2;
function vacante(datos, id, despues = calcular(simularBaja(datos, id))) {
  const sale = datos.empleados.find(e => e.id === id);
  const nivel = new Map(datos.skills.filter(s => s.nivel_validado).map(s => [`${s.empleado_id}|${s.skill_id}`, +s.nivel_validado]));
  const niv = (e, skill) => nivel.get(`${e}|${skill}`) || 0;
  const req = new Map();
  for (const f of datos.funciones.funciones) for (const s of f.skills_requeridas)
    if (niv(id, s.skill) >= s.nivel && (!req.has(s.skill) || s.nivel > req.get(s.skill).nivel)) req.set(s.skill, { skill: s.skill, nivel: s.nivel, funcion: f.id });
  const equipo = datos.empleados.filter(e => e.manager_id === id && e.estado === 'activo').map(e => e.id);
  if (equipo.length) req.set('liderazgo', { skill: 'liderazgo', nivel: NIVEL_LIDERAZGO_VACANTE, funcion: '' });
  const perfil = [...req.values()];

  const cobertura = skill => datos.empleados.filter(e => e.estado === 'activo' && e.id !== id && niv(e.id, skill) >= (req.get(skill)?.nivel || 1)).length;
  const keyPeople = new Map(despues.key_people.map(k => [k.id, k.funciones.map(f => f.funcion)]));
  const candidatos = datos.empleados.filter(e => e.estado === 'activo' && e.id !== id).map(e => {
    const brechas = perfil.filter(p => niv(e.id, p.skill) < p.nivel).map(p => ({
      skill: p.skill, tiene: niv(e.id, p.skill), necesita: p.nivel, funcion: p.funcion,
      formacion: datos.catalogo.filter(c => c.skill === p.skill && c.de === niv(e.id, p.skill) && c.a === p.nivel
        && !(c.tipo === 'mentoring-interno' && cobertura(p.skill) === 0)).map(c => c.id),
    }));
    return { id: e.id, nombre: e.nombre, rol: e.rol, area: e.area, cumple: perfil.length - brechas.length, de: perfil.length, brechas, key_person_en: keyPeople.get(e.id) || [] };
  }).filter(c => c.cumple >= Math.ceil(c.de / 2))
    .sort((a, b) => b.cumple - a.cumple || a.brechas.reduce((t, x) => t + x.necesita - x.tiene, 0) - b.brechas.reduce((t, x) => t + x.necesita - x.tiene, 0))
    .slice(0, 3);
  return { id, nombre: sale.nombre, rol: sale.rol, area: sale.area, equipo: equipo.length, perfil, candidatos };
}

// Aprobar la opción interna: el candidato asume el puesto (rol, nivel, manager), el equipo pasa a depender de él
// y se abre un plan por cada brecha de un nivel que tenga formación en el catálogo. Devuelve filas nuevas, no escribe nada.
function aplicarMovilidad(empleados, vac, candidatoId, fecha, origen) {
  const sale = empleados.find(e => e.id === vac.id);
  const nuevos = empleados.map(e =>
    e.id === candidatoId ? { ...e, rol: sale.rol, nivel_puesto: sale.nivel_puesto, manager_id: sale.manager_id, meses_con_manager_actual: '0' }
      : e.manager_id === vac.id && e.estado === 'activo' ? { ...e, manager_id: candidatoId, meses_con_manager_actual: '0' } : e);
  const c = vac.candidatos.find(x => x.id === candidatoId);
  const planes = c.brechas.filter(b => b.necesita - b.tiene === 1 && b.formacion.length).map(b => ({
    empleado_id: candidatoId, skill_id: b.skill, nivel_objetivo: b.necesita, funcion_id: b.funcion, formacion_id: b.formacion[0],
    fecha_inicio: fecha, fecha_objetivo: '', estado: 'activo', origen,
  }));
  return { empleados: nuevos, planes };
}

// Compara con una foto anterior: funciones que empeoran o mejoran
function comparar(antes, despues) {
  const previo = new Map(antes.funciones.map(f => [f.id, f]));
  return despues.funciones.flatMap(f => {
    const a = previo.get(f.id);
    if (!a) return [];
    // Cambio de color, o cambio de cobertura sin cambiar de color fuera del verde
    const d = ORDEN[f.semaforo] - ORDEN[a.semaforo] || (f.semaforo !== 'verde' ? a.cobertura - f.cobertura : 0);
    if (!d) return [];
    return [{ id: f.id, nombre: f.nombre, cambio: d > 0 ? 'empeora' : 'mejora', de: a.semaforo, a: f.semaforo, cobertura_antes: a.cobertura, cobertura_despues: f.cobertura }];
  });
}


// Propuesta de acciones (pasos 4-5): contexto para Claude y propuesta por reglas si no hay IA.
// Sin dependencias: lo usan la demo local (demo.js) y el nodo de código de n8n (exportar-n8n.js).

function contexto(r, cambios, evento, vac, datos) {
  const ids = cambios.filter(c => c.cambio === 'empeora').map(c => c.id);
  const afectadas = r.funciones.filter(x => ids.includes(x.id));
  const implicadas = new Set(afectadas.flatMap(x => x.skills.filter(s => s.semaforo !== 'verde').flatMap(s => s.personas)));
  const formaciones = new Set(afectadas.flatMap(x => x.skills.flatMap(s => s.formacion || [])));
  // Si alguna función se rediseña con IA, la recualificación sale de las formaciones de IA del catálogo
  if (afectadas.some(x => x.respuesta === 'redisenar')) datos.catalogo.filter(c => c.skill.startsWith('ia-')).forEach(c => formaciones.add(c.id));
  if (vac) {
    // Lente AI first: una skill del puesto que solo sostiene funciones a rediseñar no se cubre tal cual (ni dentro ni fuera)
    vac.perfil.forEach(p => { p.redisenar = !!p.funcion && r.funciones.find(f => f.id === p.funcion)?.respuesta === 'redisenar'; });
    vac.candidatos.forEach(c => { implicadas.add(c.id); c.brechas.forEach(b => b.formacion.forEach(x => formaciones.add(x))); });
    // Solo People: compa-ratio del candidato frente a la banda del puesto que asumiría
    const banda = datos.bandas.find(b => b.banda_id === datos.empleados.find(e => e.id === vac.id).banda_id);
    vac.candidatos.forEach(c => { c.compa_en_puesto = +(datos.empleados.find(e => e.id === c.id).salario_ficticio / banda.medio).toFixed(2); c.banda_puesto = banda.banda_id; });
  }
  return {
    evento, cambios, funciones_afectadas: afectadas, key_people: r.key_people, vacante: vac,
    senales: r.senales_rotacion.filter(s => implicadas.has(s.id)),
    catalogo: datos.catalogo.filter(c => formaciones.has(c.id)),
  };
}

// Decisión de cubrir el puesto: dos opciones excluyentes con el mismo grupo (A fuera, B el mejor candidato interno)
function opcionesVacante(ctx) {
  const v = ctx.vacante;
  if (!v || !v.perfil.some(p => p.skill !== 'liderazgo' && !p.redisenar)) return [];
  const grupo = `VAC-${v.id}`;
  const prioridad = ctx.funciones_afectadas.map(x => x.prioridad).sort()[0] || 'P1';
  const ops = [{ prioridad, funcion_id: '', tipo: 'contratar', grupo, accion: `Opción A · Buscar fuera: ${v.rol} (${v.perfil.filter(p => !p.redisenar).map(p => `${p.skill} ${p.nivel}`).join(', ')})`, empleado_id: '', skill_id: '', formacion_id: '',
    por_que: v.candidatos.length ? 'Nadie dentro cumple el perfil completo.' : 'Ningún candidato interno cumple la mitad del perfil.',
    riesgo_si_no: `Proceso de 2-3 meses; mientras tanto, ${v.equipo ? `${v.equipo} personas sin responsable` : 'sus funciones dependen de quien quede'}.` }];
  const c = v.candidatos[0];
  if (c) {
    const conForm = c.brechas.find(b => b.formacion.length);
    ops.push({ prioridad, funcion_id: c.brechas.find(b => b.funcion)?.funcion || '', tipo: 'movilidad', grupo, accion: `Opción B · Mover a ${c.nombre} (${c.rol}) a ${v.rol}`, empleado_id: c.id, skill_id: conForm?.skill || '', formacion_id: conForm?.formacion[0] || '',
      por_que: `Cumple ${c.cumple} de ${c.de} skills del puesto. Le falta: ${c.brechas.map(b => `${b.skill} ${b.tiene} → ${b.necesita}${b.formacion.length ? ` (${b.formacion[0]})` : ' (sin formación en el catálogo)'}`).join('; ')}.`,
      riesgo_si_no: c.key_person_en.length ? `Coste organizativo: ya es la única cobertura de ${c.key_person_en.join(', ')}; asumir el puesto concentra el riesgo en una persona.` : 'Coste organizativo: su puesto actual queda por cubrir.' });
  }
  return ops;
}

function propuestaPorReglas(ctx) {
  const acciones = opcionesVacante(ctx);
  const enVacante = skill => ctx.vacante?.perfil.some(p => p.skill === skill);
  for (const fn of ctx.funciones_afectadas) for (const s of fn.skills.filter(x => x.semaforo !== 'verde')) {
    const cand = (s.candidatos || []).find(c => !c.es_key_person);
    const form = ctx.catalogo.find(c => c.skill === s.skill);
    if (fn.respuesta === 'redisenar') {
      // Lente AI first: no se forma a nadie en el proceso actual; se rediseña y se recualifica
      const formIa = ctx.catalogo.find(c => c.skill === 'ia-automatizacion' && c.de === 1);
      acciones.push({ prioridad: fn.prioridad, funcion_id: fn.id, tipo: 'rediseno', accion: `Rediseñar ${fn.nombre} con IA y automatización${cand ? ` y recualificar a ${cand.nombre}` : ''}`, empleado_id: cand?.id || '', skill_id: 'ia-automatizacion', formacion_id: formIa?.id || '', por_que: `Cobertura ${s.cobertura} en ${s.skill} e impacto IA alto: formar un backup en el proceso actual es invertir en un proceso que va a cambiar.${cand?.con_interes ? ` ${cand.nombre} tiene interés declarado.` : ''}`, riesgo_si_no: `${fn.nombre} sigue dependiendo de ${s.cobertura} persona(s) y de un proceso manual.` });
      if (s.cobertura === 0) acciones.push({ prioridad: fn.prioridad, funcion_id: fn.id, tipo: 'redistribuir', accion: `Cubrir ${fn.nombre} con apoyo temporal mientras dura el rediseño`, empleado_id: '', skill_id: s.skill, formacion_id: '', por_que: 'Nadie cubre la skill hoy.', riesgo_si_no: 'La próxima entrega queda sin responsable.' });
    }
    else if (cand && s.cobertura > 0) acciones.push({ prioridad: fn.prioridad, funcion_id: fn.id, tipo: 'backup', accion: `Plan de backup: ${cand.nombre} en ${s.skill} (${s.nivel_minimo - 1} → ${s.nivel_minimo})`, empleado_id: cand.id, skill_id: s.skill, formacion_id: form?.id || '', por_que: `Cobertura ${s.cobertura}. ${cand.nombre} está a un nivel${cand.con_interes ? ' y tiene interés declarado' : ''}.`, riesgo_si_no: `La función ${fn.nombre} depende de ${s.cobertura} persona.` });
    else if (enVacante(s.skill)) { /* la cubre la decisión de la vacante (opciones A/B) */ }
    else acciones.push({ prioridad: fn.prioridad, funcion_id: fn.id, tipo: 'contratar', accion: `Abrir vacante con ${s.skill} nivel ${s.nivel_minimo}`, empleado_id: '', skill_id: s.skill, formacion_id: '', por_que: `Cobertura ${s.cobertura} y ningún candidato interno llega a tiempo.`, riesgo_si_no: `${fn.nombre} queda sin nadie que pueda sostenerla.` });
    if (s.cobertura === 1) {
      const kp = s.personas[0];
      acciones.push({ prioridad: fn.prioridad, funcion_id: fn.id, tipo: 'retencion', accion: `Conversación de permanencia con ${ctx.key_people.find(k => k.id === kp)?.nombre || kp}`, empleado_id: kp, skill_id: s.skill, formacion_id: '', por_que: 'Es la única cobertura de la skill.', riesgo_si_no: 'Una segunda salida deja la función sin cobertura.' });
    }
  }
  const n = ctx.cambios.filter(c => c.cambio === 'empeora').length;
  const nOpciones = acciones.filter(a => a.grupo).length;
  const v = nOpciones ? ctx.vacante : null, c = nOpciones > 1 ? v.candidatos[0] : null;
  const resumen = v
    ? `${ctx.evento}: ${n} función(es) empeoran. Primera decisión: cómo cubrir el puesto de ${v.rol}, buscando fuera (A)${c ? ` o moviendo a ${c.nombre} (B)` : ''}. Además se proponen ${acciones.length - nOpciones} acción(es) para reducir el riesgo mientras tanto. Todo queda pendiente de aprobación por People.`
    : `${ctx.evento}: ${n} función(es) empeoran. Se proponen ${acciones.length} acciones para su aprobación por People.`;
  const sen = c && ctx.senales.find(s => s.id === c.id);
  const detalle = c ? `${c.nombre}: probabilidad ${sen?.probabilidad || 'baja'} (${sen?.senales.join('; ') || 'sin señales'}). Si asume el puesto con su salario actual, su compa-ratio en la banda ${c.banda_puesto} sería ${c.compa_en_puesto}: la opción B exige revisar condiciones.` : '';
  return { acciones, resumen_direccion: resumen, detalle_people: detalle, observaciones: 'Propuesta generada por reglas (sin IA).' };
}

// Mensaje de usuario para prompts/proponer-acciones.md (mismo orden que la sección ## User del prompt)
function mensajeClaude(ctx) {
  const j = v => JSON.stringify(v, null, 1);
  return `Evento: ${ctx.evento}

Cambios en el mapa:
${j(ctx.cambios)}

Funciones afectadas (detalle del cálculo):
${j(ctx.funciones_afectadas)}

Key people tras el cambio:
${j(ctx.key_people)}

Señales de rotación (solo personas implicadas, confidencial People):
${j(ctx.senales)}

Vacante (puesto que deja la persona, si aplica):
