  <p>Mapa: 🔴 ${m.conteo.rojo || 0} · 🟡 ${m.conteo.ambar || 0} · 🟢 ${m.conteo.verde || 0} — <a href="${sheet}">ver hoja cobertura</a></p>
  ${opciones.length ? `<h3>Decisión · cubrir el puesto (elegir una opción)</h3>${opciones.map(tarjeta).join('')}` : ''}
